CREATE TABLE users(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),email text NOT NULL UNIQUE,created_at timestamptz NOT NULL DEFAULT now(),last_login_at timestamptz NOT NULL DEFAULT now(),stored_approved boolean NOT NULL DEFAULT false);
CREATE TABLE auth_challenges(id uuid PRIMARY KEY,email text NOT NULL,code_hash text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),expires_at timestamptz NOT NULL,attempts integer NOT NULL DEFAULT 0 CHECK(attempts BETWEEN 0 AND 5),delivered_at timestamptz,consumed_at timestamptz,superseded_at timestamptz);
CREATE INDEX challenges_email ON auth_challenges(email,created_at DESC);
CREATE TABLE sessions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES users ON DELETE CASCADE,token_hash text NOT NULL UNIQUE,created_at timestamptz NOT NULL DEFAULT now(),expires_at timestamptz NOT NULL);
CREATE TABLE rate_limit_buckets(key text PRIMARY KEY,count integer NOT NULL CHECK(count>=0),expires_at timestamptz NOT NULL);
CREATE TABLE research_operations(id uuid PRIMARY KEY,user_id uuid NOT NULL REFERENCES users ON DELETE CASCADE,action_id uuid NOT NULL,mode text NOT NULL CHECK(mode IN ('example','stored')),kind text NOT NULL,params jsonb NOT NULL,upstream_url text,status text NOT NULL CHECK(status IN ('running','complete','failed','uncertain')),reserved_credits integer NOT NULL DEFAULT 0 CHECK(reserved_credits>=0),actual_credits integer CHECK(actual_credits>=0),request_id text,error_code text,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(user_id,id));
CREATE INDEX operations_owner_time ON research_operations(user_id,created_at DESC);
CREATE TABLE budget_buckets(key text PRIMARY KEY,day text NOT NULL,requests integer NOT NULL DEFAULT 0 CHECK(requests>=0),credits integer NOT NULL DEFAULT 0 CHECK(credits>=0));
CREATE TABLE activity_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES users ON DELETE CASCADE,type text NOT NULL CHECK(type IN ('signup','signin','signout','research_success','research_failure','comparison','sharing','admin_access','access_approved','access_revoked')),mode text CHECK(mode IN ('example','stored')),created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX events_owner_time ON activity_events(user_id,created_at DESC);
CREATE TABLE accounting_retention(operation_id uuid PRIMARY KEY,reserved_credits integer NOT NULL,actual_credits integer,created_at timestamptz NOT NULL,reason text NOT NULL);
